-- parameters: ["2026-01-01", "2026-01-01"]
WITH _normal AS (SELECT region AS "region", DATE_TRUNC('quarter', balance_month) AS "balance_month", SUM(balance) AS "account_balance_last" FROM (SELECT account_id, region, balance_month, balance FROM marts.balances WHERE NOT region LIKE 'test%') AS "balances" WHERE (balance_month >= ?) GROUP BY region, DATE_TRUNC('quarter', balance_month)), _base AS (SELECT region AS "region", DATE_TRUNC('month', balance_month) AS "balance_month", SUM(balance) AS "account_balance_last" FROM (SELECT account_id, region, balance_month, balance FROM marts.balances WHERE NOT region LIKE 'test%') AS "balances" WHERE (balance_month >= ?) GROUP BY region, DATE_TRUNC('month', balance_month)), _ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY "region", DATE_TRUNC('quarter', "balance_month") ORDER BY "balance_month" DESC) AS "_rank_account_balance_last" FROM _base), _rollup AS (SELECT "region" AS "region", DATE_TRUNC('quarter', "balance_month") AS "balance_month", MAX(CASE WHEN "_rank_account_balance_last" = 1 THEN "account_balance_last" END) AS "account_balance_last" FROM _ranked GROUP BY "region", DATE_TRUNC('quarter', "balance_month")) SELECT n."region" AS "region", n."balance_month" AS "balance_month", r."account_balance_last" AS "account_balance_last" FROM _normal n JOIN _rollup r ON n."region" IS NOT DISTINCT FROM r."region" AND n."balance_month" IS NOT DISTINCT FROM r."balance_month" ORDER BY "region" ASC LIMIT 1000
